// veld — generated by veld, rewritten when veld changes. Never edit by hand.
//
// The state register.ts keeps across a reload of its own code: the context still owed
// to the next prompt, whether a dialog is on screen, and whether the conversation is a
// resumed one.
declare module 'claude-code' {
  interface PluginState {
    veld: { session: { contextPending: boolean; blocked: boolean; resumed?: boolean } }
  }
}
